CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.staff_accounts WHERE user_id=_user_id AND status='inactive') AND EXISTS(SELECT 1 FROM public.user_role_assignments a JOIN public.roles r ON r.code=a.role AND r.is_active WHERE a.user_id=_user_id AND a.is_active AND (a.role=_role::text OR (_role::text='investor' AND a.role='investor_viewer'))) $$;
CREATE OR REPLACE FUNCTION public.admin_assign_dynamic_role(_user uuid,_role text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldrows jsonb;legacy public.app_role;BEGIN IF NOT public.has_permission('security.roles','edit') OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'تعيين الدور للأدمن فقط';END IF;PERFORM public._assert_reason(_reason);IF NOT EXISTS(SELECT 1 FROM public.roles WHERE code=_role AND is_active) OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_user) THEN RAISE EXCEPTION 'دور أو مستخدم غير صالح';END IF;PERFORM pg_advisory_xact_lock(60412026,9);IF _user=auth.uid() THEN RAISE EXCEPTION 'لا يمكنك تغيير دورك';END IF;IF public.has_role(_user,'admin') AND _role<>'admin' AND (SELECT count(DISTINCT user_id) FROM public.user_role_assignments WHERE role='admin' AND is_active)<2 THEN RAISE EXCEPTION 'لا يمكن إزالة آخر أدمن';END IF;SELECT jsonb_agg(to_jsonb(a)) INTO oldrows FROM public.user_role_assignments a WHERE user_id=_user;UPDATE public.user_role_assignments SET is_active=false WHERE user_id=_user;UPDATE public.user_roles SET is_active=false WHERE user_id=_user;INSERT INTO public.user_role_assignments(user_id,role,is_active,assigned_by,reason) VALUES(_user,_role,true,auth.uid(),_reason) ON CONFLICT(user_id,role) DO UPDATE SET is_active=true,assigned_at=now(),assigned_by=auth.uid(),reason=_reason;SELECT enumlabel::public.app_role INTO legacy FROM pg_enum WHERE enumtypid='public.app_role'::regtype AND enumlabel=CASE WHEN _role='investor_viewer' THEN 'investor' ELSE _role END;IF legacy IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role,is_active) VALUES(_user,legacy,true) ON CONFLICT(user_id,role) DO UPDATE SET is_active=true;END IF;PERFORM public._safety_audit('DYNAMIC_ROLE_ASSIGNED','user_role_assignments',_user::text,oldrows,(SELECT jsonb_agg(to_jsonb(a)) FROM public.user_role_assignments a WHERE user_id=_user),_reason);END $$;
CREATE OR REPLACE FUNCTION public.admin_set_user_role(_target_user uuid,_new_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.admin_assign_dynamic_role(_target_user,_new_role::text,'تعيين دور المستخدم يدويًا');END $$;
REVOKE ALL ON FUNCTION public.admin_assign_dynamic_role(uuid,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.admin_assign_dynamic_role(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_can_read() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_permission('finance.read','view') AND NOT public.has_role(auth.uid(),'sales_agent') AND NOT public.has_role(auth.uid(),'investor') AND NOT public.has_role(auth.uid(),'control') $$;
CREATE OR REPLACE FUNCTION public.finance_assert_writer() RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role()='service_role' THEN RETURN;END IF;IF NOT public.has_permission('finance.write','edit') OR public.has_role(auth.uid(),'sales_agent') THEN RAISE EXCEPTION 'غير مسموح بكتابة المالية' USING ERRCODE='42501';END IF;END $$;
CREATE POLICY finance_sales_absolute_deny ON public.contracts AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.has_role(auth.uid(),'sales_agent')) WITH CHECK(NOT public.has_role(auth.uid(),'sales_agent'));
CREATE POLICY installments_sales_absolute_deny ON public.installments AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.has_role(auth.uid(),'sales_agent')) WITH CHECK(NOT public.has_role(auth.uid(),'sales_agent'));
CREATE POLICY receipts_sales_absolute_deny ON public.receipts AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.has_role(auth.uid(),'sales_agent')) WITH CHECK(NOT public.has_role(auth.uid(),'sales_agent'));
CREATE POLICY allocations_sales_absolute_deny ON public.receipt_allocations AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.has_role(auth.uid(),'sales_agent')) WITH CHECK(NOT public.has_role(auth.uid(),'sales_agent'));
CREATE POLICY collections_sales_absolute_deny ON public.unit_collections AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.has_role(auth.uid(),'sales_agent')) WITH CHECK(NOT public.has_role(auth.uid(),'sales_agent'));
CREATE POLICY invoices_sales_absolute_deny ON public.invoices AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.has_role(auth.uid(),'sales_agent')) WITH CHECK(NOT public.has_role(auth.uid(),'sales_agent'));
SELECT public.has_role(auth.uid(),'admin') AS current_admin_preserved,to_regprocedure('public.admin_assign_dynamic_role(uuid,text,text)') IS NOT NULL AS assignment_writer_ready;